// Fuzzer stub for: void us_base64_encode(const u8 *data, uz size, char **encoded, uz *allocated)
// Strategy:
// - Generate a random source buffer via FUZZ_PARAM_STR() and pass its data/size (clamped <= 2048 bytes).
// - Optionally preallocate an output buffer to exercise reuse/realloc paths; keep allocations <= 2048.
// - Enforce non-null outputs and track metadata on the returned buffer via attributes.

// Generate input buffer and size (<= 2048 bytes)
std::string src = FUZZ_PARAM_STR();
uz src_cap = (uz)(src.size() > 2048 ? 2048 : src.size());
unsigned int pick = *FUZZ_PARAM(unsigned int);
uz size = (uz)((pick % 9 == 0) ? 0 : src_cap); // occasionally test size=0
const u8 *data = (const u8*)src.data(); // src.data() is valid for src.size() bytes

// Prepare encoded pointer and capacity; may be updated by the API
char *encoded_local = nullptr;
uz allocated_local = 0;

// Optionally preallocate to cover code paths that reuse or realloc the buffer
unsigned int mode = *FUZZ_PARAM(unsigned int);
if ((mode & 1u) == 0u) {
    // Base64 worst-case: ceil(n/3)*4 + 1 for NUL (conventional)
    uz needed = size ? (uz)((((size + 2) / 3) * 4) + 1) : (uz)1;
    uz tweak_sel = (uz)((mode >> 1) % 3); // 0=exact, 1=undersize, 2=oversize
    if (tweak_sel == 0) {
        allocated_local = needed;
    } else if (tweak_sel == 1) {
        allocated_local = needed > 2 ? (needed - 2) : needed; // force potential realloc
    } else {
        allocated_local = needed + 8; // oversized
    }
    if (allocated_local > (uz)2048) { allocated_local = (uz)2048; }
    encoded_local = (char*)malloc((size_t)allocated_local);
    if (!encoded_local) { FUZZ_BAIL(); }
}

// Invoke the target function; it may modify both pointer and capacity
us_base64_encode(data, size, &encoded_local, &allocated_local);

// Validate postconditions: outputs must be usable by downstream callers
if (!encoded_local) { FUZZ_BAIL(); }
if (allocated_local == 0) { FUZZ_BAIL(); }

// Best-effort check for NUL-termination within the advertised capacity (not required, but tracked)
int null_terminated = 0;
{
    uz scan_lim = allocated_local;
    if (scan_lim > (uz)2048) scan_lim = (uz)2048; // limit scan for performance
    for (uz i = 0; i < scan_lim; ++i) {
        if (encoded_local[i] == '\0') { null_terminated = 1; break; }
    }
}

// Provide outputs to fuzzer runtime
void *encoded_buf = (void*)encoded_local; // ownership transferred to runtime
uz *encoded_capacity = new uz;            // persistent metadata object
*encoded_capacity = allocated_local;

// Attach attributes describing this buffer for downstream stubs
FUZZ_SET_ATTR_STR(encoded_buf, "type", "base64_buffer");
int cap_int = (int)(allocated_local > (uz)0x7fffffff ? 0x7fffffff : (unsigned long long)allocated_local);
FUZZ_SET_ATTR_INT(encoded_buf, "capacity", cap_int);
FUZZ_SET_ATTR_INT(encoded_buf, "null_terminated", null_terminated);
FUZZ_SET_ATTR_INT(encoded_buf, "owned", 1);

// Validation summary:
// - data points to at least 'size' bytes from std::string storage.
// - encoded_buf is non-null; encoded_capacity reflects allocated size; attributes capture buffer properties.

