import random

# Target: us_base64_encode(const u8 *data, uz size, char **encoded, uz *allocated)
# Generate arbitrary binary buffers up to 2048 bytes. Deterministic via seed.

_MAX = 2048


def _asc_sequence(n: int, start: int = 0) -> bytes:
    return bytes(((start + i) & 0xFF) for i in range(n))


def _desc_sequence(n: int, start: int = 255) -> bytes:
    return bytes(((start - i) & 0xFF) for i in range(n))


def _alt_patterns(n: int, a: int = 0x00, b: int = 0xFF) -> bytes:
    return bytes((a if (i & 1) == 0 else b) for i in range(n))


def _repeat_byte(n: int, b: int) -> bytes:
    return bytes([b] * n)


def _text_like(n: int) -> bytes:
    # Printable ASCII with whitespace
    chars = [ord(' '), ord('\t'), ord('\n'), ord('\r')] + list(range(0x21, 0x7F))
    return bytes(random.choice(chars) for _ in range(n))


def _random_bytes(n: int) -> bytes:
    return bytes(random.getrandbits(8) for _ in range(n))


def _structured_blocks(total: int) -> bytes:
    parts = []
    remaining = total
    while remaining > 0:
        if random.random() < 0.8:
            k = random.randint(1, min(16, remaining))
        else:
            k = random.randint(1, remaining)
        choice = random.randint(0, 6)
        if choice == 0:
            parts.append(_asc_sequence(k, random.randint(0, 255)))
        elif choice == 1:
            parts.append(_desc_sequence(k, random.randint(0, 255)))
        elif choice == 2:
            parts.append(_alt_patterns(k, random.randint(0, 255), random.randint(0, 255)))
        elif choice == 3:
            parts.append(_repeat_byte(k, random.randint(0, 255)))
        elif choice == 4:
            parts.append(_text_like(k))
        elif choice == 5:
            parts.append(_random_bytes(k))
        else:
            if random.random() < 0.5:
                parts.append(_repeat_byte(k, 0x00))
            else:
                parts.append(bytes(0x80 + (random.getrandbits(8) & 0x7F) for _ in range(k)))
        remaining -= k
    return b"".join(parts)


def _sizes_for_padding(max_len: int) -> list:
    sizes = [0, 1, 2, 3, 4, 5]
    for base in [3, 12, 63, 255, 512, 1023, 1500]:
        for delta in (-2, -1, 0, 1, 2):
            n = base + delta
            if 0 <= n <= max_len:
                sizes.append(n)
    sizes = sorted(set(x for x in sizes if x <= max_len))
    return sizes


def _safe_randint(a: int, b: int) -> int:
    # Returns a in case b < a to avoid empty ranges
    if b < a:
        return a
    return random.randint(a, b)


def _make_payload(choice: int) -> bytes:
    sizes = _sizes_for_padding(_MAX)

    if choice == 0:
        return b""  # empty buffer
    elif choice == 1:
        return b"A"
    elif choice == 2:
        return b"AB"
    elif choice == 3:
        return b"ABC"
    elif choice == 4:
        return b"ABCD"
    elif choice == 5:
        return b"ABCDE"
    elif choice == 6:
        n = random.choice([s for s in sizes if s % 3 == 2 and s > 0])
        return _asc_sequence(n)
    elif choice == 7:
        n = random.choice([s for s in sizes if s % 3 == 1 and s > 0])
        return _desc_sequence(n)
    elif choice == 8:
        n = random.choice([s for s in sizes if s % 3 == 0 and s > 0])
        return _alt_patterns(n, 0x00, 0xFF)
    elif choice == 9:
        n = random.choice([64, 128, 256, 512, 1024, 1500, 2000])
        n = min(n, _MAX)
        return _text_like(n)
    elif choice == 10:
        n = random.randint(1, _MAX)
        return _random_bytes(n)
    elif choice == 11:
        vals = [0x00, 0x20, 0x7F, 0x80, 0xFF]
        parts = []
        remaining = random.randint(1, _MAX)
        while remaining > 0:
            bval = random.choice(vals)
            k = random.randint(1, min(64, remaining))
            parts.append(_repeat_byte(k, bval))
            remaining -= k
        return b"".join(parts)
    elif choice == 12:
        n = random.randint(1, _MAX)
        return _structured_blocks(n)
    elif choice == 13:
        hdr = b"Content-Type: application/octet-stream\r\n\r\n"
        max_body = max(0, _MAX - len(hdr))
        n = _safe_randint(0, max_body)
        return hdr + _random_bytes(n)
    elif choice == 14:
        # Prominent NUL runs at start/middle/end; guard empty randint ranges
        n = random.randint(1, _MAX)
        core = _random_bytes(n)
        max_prefix = min(16, max(0, _MAX - len(core)))
        prefix_len = _safe_randint(1, max_prefix) if max_prefix >= 1 else 0
        prefix = b"\x00" * prefix_len
        max_mid = min(16, max(0, _MAX - len(core) - len(prefix)))
        mid_len = _safe_randint(1, max_mid) if max_mid >= 1 else 0
        mid = b"\x00" * mid_len
        max_suffix_cap = max(0, _MAX - len(core) - len(prefix) - len(mid))
        max_suffix = min(16, max_suffix_cap)
        suffix_len = _safe_randint(0, max_suffix) if max_suffix >= 0 else 0
        first_half = core[: max(0, (len(core) // 2))]
        second_half = core[max(0, (len(core) // 2)) :]
        blob = prefix + first_half + mid + second_half + (b"\x00" * suffix_len)
        return blob[:_MAX]
    elif choice == 15:
        vocab = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/="
        n = random.randint(1, _MAX)
        return bytes(random.choice(vocab) for _ in range(n))
    else:
        base = random.randint(0, _MAX)
        base -= base % 3
        base += random.choice([-2, -1, 0, 1, 2])
        n = max(0, min(_MAX, base))
        if n == 0:
            return b""
        return _structured_blocks(n)


def generate(seed: int) -> bytes:
    random.seed(seed)
    choice = random.randint(0, 16)
    data = _make_payload(choice)
    if len(data) > _MAX:
        data = data[:_MAX]
    return data
